def check_endpoint(value, label):
    import ipaddress, urllib.parse
    parsed = urllib.parse.urlsplit(value)
    if parsed.scheme not in ('http', 'https') or not parsed.hostname:
        sys.exit('The ' + label + ' must be an http(s) URL with a host.')
    host = parsed.hostname
    local = host == 'localhost' or host.endswith('.localhost')
    try:
        address = ipaddress.ip_address(host)
        local = local or address.is_loopback or address.is_private
    except ValueError:
        local = local or '.' not in host
    if parsed.scheme == 'http' and not local:
        sys.exit('Plain http is allowed only for a local ' + label + '; use https for a remote host.')
    return value

